public class CounterPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            CounterPanel panel = new CounterPanel();
            java.awt.Component label = find(panel, "count");
            java.awt.Component plus = find(panel, "plus");
            java.awt.Component minus = find(panel, "minus");
            check("count label starts at 0", "0", textOf(label));
            if (plus instanceof javax.swing.JButton && minus instanceof javax.swing.JButton) {
                javax.swing.JButton p = (javax.swing.JButton) plus;
                javax.swing.JButton m = (javax.swing.JButton) minus;
                p.doClick();
                p.doClick();
                p.doClick();
                check("after three plus clicks", "3", textOf(label));
                m.doClick();
                check("after one minus click", "2", textOf(label));
                m.doClick();
                m.doClick();
                check("back down to zero", "0", textOf(label));
                m.doClick();
                check("minus never goes below zero", "0", textOf(label));
                p.doClick();
                check("counting works again after hitting zero", "1", textOf(label));
            } else {
                failures++;
                System.out.println("FAIL  plus or minus button not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

