import java.awt.event.ActionEvent;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class CounterPanel extends JPanel {

    private final JLabel count = new JLabel("0");
    private final JButton plus = new JButton("+");
    private final JButton minus = new JButton("-");
    private int value = 0;

    public CounterPanel() {
        count.setName("count");
        plus.setName("plus");
        minus.setName("minus");
        add(minus);
        add(count);
        add(plus);
        plus.addActionListener(this::onPlus);
        minus.addActionListener(this::onMinus);
    }

    private void onPlus(ActionEvent e) {
        value++;
        count.setText(String.valueOf(value));
    }

    private void onMinus(ActionEvent e) {
        if (value > 0) {
            value--;
        }
        count.setText(String.valueOf(value));
    }
}
